def word_count_ascii(s: str) -> list[list[str, int]]:
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isalpha() and ord(s[i]) < 128:
            j = i
            while j < n and s[j].isalpha() and ord(s[j]) < 128:
                j += 1
            word = s[i:j].lower()
            found = False
            for entry in result:
                if entry[0] == word:
                    entry[1] += 1
                    found = True
                    break
            if not found:
                result.append([word, 1])
            i = j
        else:
            i += 1
    result.sort(key=lambda x: x[0])
    return result

